# Public API (cm:*)
  @api cm:setContext(newTake)  @ 416-421
      @contract  setContext(nil) clears take+track; setContext(take) derives track via GetMediaItemTrack  @ 414
      @contract  refreshes all persisted caches (transient resets to {}) and fires configChanged {}  @ 415
  @api cm:clearTake()  @ 423-428
  @api cm:boundTake()  @ 431
      @contract  bound take pointer; nil when context is cleared (take/track tiers resolve off empty)  @ 430
  @api cm:boundTrack()  @ 434
      @contract  bound track pointer; nil when context is cleared (track tier resolves off empty)  @ 433
  @api cm:setTrack(newTrack)  @ 436-441
  @api cm:pollUndo()  @ 444
      @contract  delegates to the engine watcher; cm's watch group reloads tiers and fires configChanged  @ 443
  @api cm:isDeclared(key)  @ 481
      @contract  non-raising existence test against the schema; true iff key is declared  @ 480
  @api cm:get(key, opts)  @ 485-489
      @contract  deep-copy of resolved value (most-specific tier, else default); raises on unknown key  @ 483
      @contract  opts.mergeTiers=true → per-subkey union across defaults+tiers; table-valued keys only  @ 484
  @api cm:getAt(level, key)  @ 492-501
      @contract  reads single tier only (no merge, no defaults); key nil → whole-cache clone  @ 491
  @api cm:valueFor(handle, scope, key)  @ 504-511
      @contract  single-tier value for a foreign take/track handle (ps:getAt); no merge or defaults  @ 503
  @api cm:defaultFor(key)  @ 514-517
      @contract  deep-copy of the schema default for key (no tiers, no merge); raises on unknown key  @ 513
  -- Writing
  @api cm:set(level, key, value)  @ 522-532
      @contract  deep-copies value into tier cache, persists, fires targeted configChanged  @ 521
  @api cm:remove(level, key)  @ 535-546
      @contract  removes key from named tier; no-op (no signal) if that tier's cache is unloaded  @ 534
  @api cm:assign(level, updates)  @ 549-563
      @contract  validates all keys before any write (all-or-nothing); REMOVE deletes; fires signal  @ 548

